def bfs_all_depths(graph, start):
    """Perform BFS and return the maximum depth reached and nodes at each depth."""
    visited = set()
    queue = deque([(start, 0)])
    depth_map = defaultdict(set)
    max_depth = 0

    while queue:
        node, depth = queue.popleft()

        if node in visited:
            continue
        visited.add(node)

        depth_map[depth].add(node)
        max_depth = max(max_depth, depth)

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                queue.append((neighbor, depth + 1))

    return depth_map, max_depth

